class Solution { public:
    string largestPalindromic(string num) {
        int f[10]={};for(char c:num)++f[c-'0'];
        string left;
        for(int d=9;d>=1;--d){left.append(f[d]/2,char('0'+d));f[d]%=2;}
        if(!left.empty()){left.append(f[0]/2,'0');f[0]%=2;}
        char mid=0;for(int d=9;d>=0;--d)if(f[d]){mid=char('0'+d);break;}
        string right=left;reverse(right.begin(),right.end());
        if(left.empty()&&!mid)return "0";
        return left+(mid?string(1,mid):string())+right;
    }
};
